import {TYPES,getFlow} from './model.mjs';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function moduleLibraryHTML(groups,collapsed){
 const rows=(items,depth=0)=>items.map(item=>{const color=TYPES[item.type||'compute'],nested=!!item.children,closed=collapsed.has(item.id);return `<div class="module-entry"><div class="module-row"><button class="module-card ${nested?'module-parent':''}" data-module-id="${escape(item.id)}" aria-label="拖入 ${escape(item.name)}" title="拖动放入泳道${nested?'，包含预置子流程':''}" style="--module-fill:${color.fill};--module-ink:${color.stroke}"><svg viewBox="0 0 30 24" aria-hidden="true"><path d="M3 4Q14 3 27 4L26 20 3 20Z" fill="${color.fill}" stroke="${color.stroke}" stroke-width="1.1"/>${nested?'<path d="M8 9h14M8 13h10M8 17h14" fill="none" stroke="'+color.stroke+'" stroke-width=".8"/>':''}</svg><span>${escape(item.name)}</span></button>${nested?`<button class="module-toggle" data-module-toggle="${escape(item.id)}" aria-label="${closed?'展开':'收起'} ${escape(item.name)} 分类" aria-expanded="${!closed}">${closed?'›':'⌄'}</button>`:''}${item.flow?`<button class="module-delete" data-module-delete="${escape(item.id)}" aria-label="移除自定义模块 ${escape(item.name)}">×</button>`:''}</div>${nested?`<div class="module-children" ${closed?'hidden':''}>${rows(item.children,depth+1)}</div>`:''}</div>`;}).join('');
 return groups.map(group=>`<section class="module-section"><div class="module-heading"><button data-module-id="${escape(group.id)}" class="module-category" title="拖入整个分类">${escape(group.name)}</button><button class="module-toggle" data-module-toggle="${escape(group.id)}" aria-label="${collapsed.has(group.id)?'展开':'收起'} ${escape(group.name)} 分类" aria-expanded="${!collapsed.has(group.id)}">${collapsed.has(group.id)?'›':'⌄'}</button></div><div ${collapsed.has(group.id)?'hidden':''}>${group.id==='custom'?'<button id="save-module-btn" class="save-module-btn">＋ 封装当前流程</button>':''}${rows(group.children)}${group.id==='custom'&&!group.children.length?'<p class="module-empty">把画好的整个流程保存成模块，<br>下次直接拖入使用。</p>':''}</div></section>`).join('');
}
export function tabsHTML(root,tabs,active){return tabs.map(tab=>{const p=tab.path,parent=p.length?getFlow(root,p.slice(0,-1)):null,name=p.length?parent?.nodes.find(n=>n.id===p.at(-1))?.text||'未命名过程':'主流程',k=p.join('/'),current=k===active.join('/');return`<div class="flow-tab ${current?'active':''}" role="presentation"><button data-navigate="${k}" ${current?'aria-current="page"':''} title="${escape(name)}">${escape(name.slice(0,28))}</button>${p.length?`<button class="flow-tab-close" data-close-flow="${k}" aria-label="关闭子流程 ${escape(name)}">×</button>`:''}</div>`;}).join('');}
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
let portal=null,opening=null;
export function stopFlowAnimation(){opening?.cancel();opening=null;portal?.remove();portal=null;const viewport=document.querySelector('#viewport');if(viewport)delete viewport.dataset.transition;}
export function animateFlowOpen(viewport,from){stopFlowAnimation();if(!from||reduced())return;const r=viewport.getBoundingClientRect();viewport.dataset.transition='opening';opening=viewport.animate([{transform:`translate(${from.x-r.x}px,${from.y-r.y}px) scale(${Math.max(.02,from.width/r.width)},${Math.max(.02,from.height/r.height)})`,opacity:.6,borderRadius:'10px'},{transform:'none',opacity:1,borderRadius:'0px'}],{duration:320,easing:'cubic-bezier(.2,.75,.25,1)'});const a=opening;a.finished.catch(()=>{}).finally(()=>{if(opening===a){delete viewport.dataset.transition;opening=null;}});}
export function captureFlow(viewport,svg){if(reduced())return null;const r=viewport.getBoundingClientRect(),s=svg.getBoundingClientRect(),frame=document.createElement('div');frame.className='flow-shrink-preview';Object.assign(frame.style,{left:r.x+'px',top:r.y+'px',width:r.width+'px',height:r.height+'px'});const image=new Image();image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(svg));Object.assign(image.style,{position:'absolute',left:s.x-r.x+'px',top:s.y-r.y+'px',width:s.width+'px',height:s.height+'px',maxWidth:'none'});frame.append(image);return frame;}
export function animateFlowClose(frame,to){stopFlowAnimation();if(!frame||!to)return;portal=frame;document.body.append(frame);const r=frame.getBoundingClientRect();frame.animate([{transform:'none',opacity:1},{transform:`translate(${to.x-r.x}px,${to.y-r.y}px) scale(${Math.max(.02,to.width/r.width)},${Math.max(.02,to.height/r.height)})`,opacity:.15}],{duration:300,easing:'cubic-bezier(.35,.05,.65,.95)',fill:'forwards'}).finished.catch(()=>{}).finally(()=>{frame.remove();if(portal===frame)portal=null;});}
